15	// V2: Fans out brand status change notifications (active/deactivated) to all connected affiliates.
16	class FanOutBrandStatusNotificationJob implements ShouldQueue
17	{
18	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
19	
20	    public int $tries = 1;
21	
22	    public function __construct(
23	        public readonly string $brandProfessionalId,
24	        public readonly string $brandStatus, // 'active' | 'deactivated'
25	    ) {
26	        $this->onQueue('notifications');
27	    }
28	
29	    public function handle(NotificationPublisher $publisher): void
30	    {
31	        $brand = Professional::find($this->brandProfessionalId);
32	
33	        if (! $brand) {
34	            Log::warning('FanOutBrandStatusNotificationJob: brand not found, skipping fan-out', [
35	                'brand_professional_id' => $this->brandProfessionalId,
36	            ]);
37	
38	            return;
39	        }
40	
41	        $yearWeek = now()->format('o-W');
42	
43	        $brandName = (string) ($brand->display_name ?: $brand->handle ?: 'Brand');
44	
45	        $affiliateIds = DB::table('brand.brand_partner_links')
46	            ->where('brand_professional_id', $this->brandProfessionalId)
47	            ->pluck('affiliate_professional_id');
48	
49	        foreach ($affiliateIds as $affiliateId) {
50	            try {
51	                if ($this->brandStatus === 'deactivated') {
52	                    $publisher->publish(
53	                        professionalId: $affiliateId,
54	                        frontendType: 'Warning',
55	                        category: 'brand_status',
56	                        title: 'Brand program deactivated',
57	                        body: "{$brandName}'s affiliate program has been deactivated.",
58	                        dedupeKey: "brand.deactivated.{$this->brandProfessionalId}.{$yearWeek}",
59	                        ctaUrl: '/account/store',
60	                        retentionConfigKey: 'brand_status',
61	                    );
62	                } else {
63	                    $publisher->publish(
64	                        professionalId: $affiliateId,
65	                        frontendType: 'Info',
66	                        category: 'brand_status',
67	                        title: 'Brand program reactivated',
68	                        body: "{$brandName}'s affiliate program is now active.",
69	                        dedupeKey: "brand.reactivated.{$this->brandProfessionalId}.{$yearWeek}",
70	                        ctaUrl: '/account/store',
71	                        retentionConfigKey: 'brand_status',
72	                    );
73	                }
74	            } catch (\Throwable $e) {
75	                Log::warning('FanOutBrandStatusNotificationJob affiliate notify failed', [
76	                    'affiliate_id' => $affiliateId,
77	                    'message' => $e->getMessage(),
78	                ]);
79	            }
80	        }
81	    }
82	
83	    public function failed(\Throwable $e): void
84	    {
85	        Log::error('Brand status fan-out job failed', [
86	            'brand_professional_id' => $this->brandProfessionalId,
87	            'brand_status' => $this->brandStatus,
88	            'message' => $e->getMessage(),
89	        ]);
90	    }
91	}
